// The matched substring is wrapped in its own <span>, so the anchor's text is
        // split across child nodes - normalize-space(.) is needed to see the full label,
        // not normalize-space(text()) which only sees direct text-node children.
        // The suggestion label's DOM text case (e.g. "Atorvastatin Calcium") doesn't match
        // the case CSS renders it in (e.g. "atorvastatin calcium") or our oracle data's
        // case (e.g. "LIPITOR"), so the comparison is done case-insensitively via translate().
        By suggestion = By.xpath(
                "//a[contains(concat(' ', normalize-space(@class), ' '), ' result-row ') "
                        + "and translate(normalize-space(.), '" + UPPER + "', '" + LOWER + "')='"
                        + exactSuggestionText.toLowerCase() + "']");

        TimeoutException lastError = null;
        for (int attempt = 1; attempt <= SEARCH_RETRY_ATTEMPTS; attempt++) {
            dismissSignInNagIfPresent();
            type(SEARCH_INPUT, searchTerm);
            try {
                new WebDriverWait(driver, SUGGESTION_APPEAR_TIMEOUT)
                        .until(ExpectedConditions.elementToBeClickable(suggestion))
                        .click();
                return this;
            } catch (TimeoutException e) {
                lastError = e;
            }
        }
        throw lastError;

searchAndSelectMedicine(searchTerm, exactSuggestionText);
        selectStrength(strengthText);
        setQuantity(quantity);
        selectFrequency(frequencyText);
        return submitAddMedicineForm();

By card = By.xpath(
                "//*[contains(@class,'medicine-information-container')]"
                        + "[.//a[contains(@class,'medicine-name') and normalize-space(text())='" + exactDrugName + "']]");
        return waitVisible(card);

WebElement card = findResultCard(exactDrugName);
        card.findElement(By.cssSelector("a.medicine-name")).click();
        return new MedicineDetailsPage(driver);

selectHealthPlan(planName);
        if (isMedicarePartDPromptDisplayed()) {
            selectMedicarePartD(medicarePartDAnswer);
        }
        click(CONTINUE_BUTTON);
        return new HomePage(driver);

