ExpectedDrug expected = TestDataLoader.findDrugByKey("ATORVASTATIN_GENERIC");

                MedicineSearchPage searchPage = goToFindMedicinesAsGuest()
                                .addMedicine(expected.getSearchTerm(), expected.getSuggestionText(),
                                                expected.getStrength(), expected.getQuantity(),
                                                expected.getFrequency());

                Assert.assertEquals(searchPage.getCardDoseInfo(expected.getExpectedName()),
                                expected.getExpectedDoseInfo(),
                                "Dose info on the result card did not match expected dosage/quantity");
                Assert.assertEquals(searchPage.getCardFormularyText(expected.getExpectedName()),
                                expected.getCardFormularyText(),
                                "Formulary status on the result card did not match expected value");

                MedicineDetailsPage detailsPage = searchPage.openMedicineDetails(expected.getExpectedName());

                Assert.assertEquals(detailsPage.getDrugName(), expected.getExpectedName());
                Assert.assertEquals(detailsPage.getDoseInfo(), expected.getExpectedDoseInfo());
                Assert.assertEquals(detailsPage.getFormularyStatusHeading(), expected.getDetailFormularyHeading(),
                                "Expected this generic to be marked \"On drug list\" on the details page");
                Assert.assertEquals(detailsPage.getTierHeading(), expected.getDetailTierHeading());
                Assert.assertTrue(expected.isOnDrugList(),
                                "Test data sanity check: this drug should be flagged onDrugList=true");

ExpectedDrug expected = TestDataLoader.findDrugByKey("LIPITOR_BRAND");

                MedicineSearchPage searchPage = goToFindMedicinesAsGuest()
                                .addMedicine(expected.getSearchTerm(), expected.getSuggestionText(),
                                                expected.getStrength(), expected.getQuantity(),
                                                expected.getFrequency());

                Assert.assertEquals(searchPage.getCardDoseInfo(expected.getExpectedName()),
                                expected.getExpectedDoseInfo(),
                                "Dose info on the result card did not match expected dosage/quantity");
                Assert.assertEquals(searchPage.getCardFormularyText(expected.getExpectedName()),
                                expected.getCardFormularyText(),
                                "Formulary status on the result card did not match expected value");

                MedicineDetailsPage detailsPage = searchPage.openMedicineDetails(expected.getExpectedName());

                Assert.assertEquals(detailsPage.getDrugName(), expected.getExpectedName());
                Assert.assertEquals(detailsPage.getDoseInfo(), expected.getExpectedDoseInfo());
                Assert.assertEquals(detailsPage.getFormularyStatusHeading(), expected.getDetailFormularyHeading(),
                                "Expected this brand drug to be marked \"Not on drug list\" on the details page");
                Assert.assertEquals(detailsPage.getTierHeading(), expected.getDetailTierHeading());
                Assert.assertFalse(expected.isOnDrugList(),
                                "Test data sanity check: this drug should be flagged onDrugList=false");

MedicineSearchPage searchPage = goToFindMedicinesAsGuest();

                Assert.assertEquals(searchPage.getSelectedHealthPlan(), ConfigReader.healthPlan(),
                                "Find medicines page did not show the health plan selected during the guest flow");
